const e = $json;
const row = ($items("DQ1 - Delivery Quote (DB)")[0]?.json || {});
const strictAr = (($env.STRICT_AR_OUT || 'true').toString().toLowerCase() === 'true');
const msgIn = ((e.message?.text || '') + ' ' + (e.userText || '')).toString();
const hasArabic = /[؀-ۿݐ-ݿࢠ-ࣿ]/.test(msgIn);
const locHint = (e.debug?.responseLocale || e.state?.localePref || e.state?.locale || 'fr').toString().toLowerCase();
const locale = (strictAr && hasArabic) ? 'ar' : (locHint.startsWith('ar') ? 'ar' : 'fr');

const ok = (row.reason === 'OK');
if (!e.state) e.state = {};
if (!e.state.delivery) e.state.delivery = {};
e.state.delivery.quote_shown = true;

function money(cents) {
  const n = Number(cents || 0);
  return (n/100).toFixed(2);
}

let reply = '';
let buttons = [];

if (!ok) {
  const code = (row.reason || 'DELIVERY_ZONE_NOT_FOUND').toString();
  if (locale === 'ar') {
    if (code === 'DELIVERY_ZONE_NOT_FOUND') reply = '🚫 التوصيل غير متوفر لهذه المنطقة. أرسل: الولاية / البلدية / العنوان / الهاتف.';
    else if (code === 'DELIVERY_ZONE_INACTIVE') reply = '🚫 التوصيل غير متوفر حالياً لهذه المنطقة. اختر: في المطعم أو للطلب الخارجي.';
    else if (code === 'DELIVERY_MIN_ORDER') reply = `🛵 الحد الأدنى للتوصيل هو ${money(row.min_order_cents)}. أضف للطلب أو غيّر طريقة الخدمة.`;
    else reply = `🚫 التوصيل غير متوفر (${code}). أعد إرسال: الولاية / البلدية / العنوان / الهاتف.`;
    buttons = [
      {id:'MODE_A_EMPORTER',title:'🛍️ للطلب الخارجي'},
      {id:'MODE_SUR_PLACE',title:'🍽️ في المطعم'},
      {id:'CONFIRM_NO',title:'✏️ تعديل'}
    ];
  } else {
    if (code === 'DELIVERY_ZONE_NOT_FOUND') reply = '🚫 Livraison indisponible pour cette zone. Envoie : Wilaya / Commune / Adresse / Tel.';
    else if (code === 'DELIVERY_ZONE_INACTIVE') reply = '🚫 Livraison indisponible sur cette zone (inactive). Choisis : sur place ou à emporter.';
    else if (code === 'DELIVERY_MIN_ORDER') reply = `🛵 Minimum livraison : ${money(row.min_order_cents)}. Ajoute au panier ou change de mode.`;
    else reply = `🚫 Livraison indisponible (${code}). Envoie : Wilaya / Commune / Adresse / Tel.`;
    buttons = [
      {id:'MODE_A_EMPORTER',title:'🛍️ À emporter'},
      {id:'MODE_SUR_PLACE',title:'🍽️ Sur place'},
      {id:'CONFIRM_NO',title:'✏️ Modifier'}
    ];
  }
} else {
  const fee = Number(row.final_fee_cents||0);
  const minO = Number(row.min_order_cents||0);
  const etaMin = row.eta_min ?? '';
  const etaMax = row.eta_max ?? '';
  const feeTxt = (fee === 0)
    ? (locale === 'ar' ? 'مجاني' : 'Gratuit')
    : money(fee);

  if (locale === 'ar') {
    reply = `🚚 التوصيل متاح ✅\nرسوم التوصيل: ${feeTxt}\nالحد الأدنى: ${money(minO)}\nالوقت المتوقع: ${etaMin}-${etaMax} دقيقة`;
  } else {
    reply = `🚚 Livraison OK ✅\nFrais : ${feeTxt}\nMin commande : ${money(minO)}\nETA : ${etaMin}-${etaMax} min`;
  }

  const slotsEnabled = ($json.config?.delivery_slots_enabled ?? ($env.DELIVERY_SLOTS_ENABLED === 'true'));
  if (slotsEnabled) {
    const slots = $items("DQ3 - List Slots (DB)").map(i => i.json).filter(s => Number(s.remaining||0)>0);
    if (slots.length) {
      e.state.stage = 'DELIVERY_SLOT_PICK';
      reply += (locale === 'ar') ? `\n\nاختر وقت التوصيل:` : `\n\nChoisis un créneau :`;
      buttons = slots.slice(0,4).map(s => ({
        id:`SLOT_${s.slot_id}`,
        title:`🕒 ${s.start_time}-${s.end_time} (${s.remaining})`
      }));
      buttons.push({id:'CONFIRM_NO',title: (locale==='ar' ? '✏️ تعديل' : '✏️ Modifier')});
    } else {
      reply += (locale === 'ar') ? `\n\nلا توجد أوقات متاحة اليوم.` : `\n\nPlus de créneaux disponibles aujourd’hui.`;
      buttons = [{id:'CHECKOUT',title:(locale==='ar'?'✅ تأكيد':'✅ Valider')},{id:'CONFIRM_NO',title:(locale==='ar'?'✏️ تعديل':'✏️ Modifier')}];
    }
  } else {
    buttons = [{id:'CHECKOUT',title:(locale==='ar'?'✅ تأكيد':'✅ Valider')},{id:'CONFIRM_NO',title:(locale==='ar'?'✏️ تعديل':'✏️ Modifier')}];
  }
}

e.response = {replyText: reply, buttons};
e.debug = {...(e.debug||{}), deliveryQuoteReason: (row.reason||null), responseLocale: locale};
return [{json: e}];

