const e = $json;
const row = $json; // create_order returns columns on current item
const orderId = row.order_id || row.orderid || row.id;
const total = Number(row.total_cents || 0);
const summary = row.summary || '';

const replyText = `✅ Commande confirmée !\nID: ${orderId}\n${summary}\nTotal: ${(total/100).toFixed(2)}€\nMerci 🙏`;

return [{json:{
  ...e,
  response: {
    replyText,
    buttons: [{id:'FEEDBACK_LATER',title:'⭐ Donner un avis'}]
  },
  actions: { sendToKitchen: true },
  debug: { ...(e.debug||{}), orderId, totalCents: total }
}}];

const e = $json;
const resp = e.response || { replyText: 'OK', buttons: [] };

const out = {
  channel: e.channel,
  tenantId: e.tenantId || '',
  restaurantId: e.restaurantId,
  conversationKey: e.conversationKey || '',
  userId: e.userId,
  orderId: e.debug?.orderId || null,
  replyText: resp.replyText || '',
  buttons: Array.isArray(resp.buttons) ? resp.buttons : [],
  attachments: Array.isArray(resp.attachments) ? resp.attachments : [],
  actions: e.actions || { sendToKitchen:false },
  debug: {
    traceId: e.metadata?.msgId || '',
    intent: e.intent || '',
    riskFlags: e.debug?.riskFlags || []
  }
};
return [{json: out}];

const crypto = require('crypto');
const out = $json;

const ch = (out.channel || '').toString();
const orderId = out.orderId ? out.orderId.toString() : '';
const traceId = (out.debug?.traceId || '').toString();

const dedupeKey = orderId
  ? `order:${orderId}:${ch}:reply`
  : `msg:${ch}:${traceId || crypto.randomUUID()}`;

const payload = {
  channel: ch,
  to: out.userId,
  restaurantId: out.restaurantId,
  text: out.replyText,
  buttons: out.buttons || [],
  attachments: out.attachments || [],
  meta: { intent: out.debug?.intent || '' }
};

return [{
  json: {
    ...out,
    outbox_dedupe_key: dedupeKey,
    outbox_template: 'reply',
    outbox_payload: payload
  }
}];

const e = $json;
return [{
  json: {
    ...e,
    _send: {
      ok: true,
      queued: true,
      outboundId: e.outbound_id || e.outboundid || e.outbound_id,
      status: e.status || 'PENDING'
    }
  }
}];

